    private static final VoxelShape[] SHAPES = new VoxelShape[4];
    private static final long CONSTRUCTION_NANOS;
    static {
        long start=System.nanoTime();
        for (int turns=0; turns<4; turns++) {
            double[][] rotated=new double[BOXES.length][];
            for (int n=0;n<BOXES.length;n++) {
                double[] box=BOXES[n];
                double x0=box[0],z0=box[2],x1=box[3],z1=box[5];
                for(int i=0;i<turns;i++){double a=x0,b=x1;x0=16-z1;x1=16-z0;z0=a;z1=b;}
                rotated[n]=new double[]{x0/16,box[1]/16,z0/16,x1/16,box[4]/16,z1/16};
            }
            double[] xs=coordinates(rotated,0),ys=coordinates(rotated,1),zs=coordinates(rotated,2);
            long cells=(long)(xs.length-1)*(ys.length-1)*(zs.length-1);
            if(cells>32_000_000L)throw new IllegalStateException("Double-support collision grid exceeds bounded budget");
            BitSetDiscreteVoxelShape bits=new BitSetDiscreteVoxelShape(xs.length-1,ys.length-1,zs.length-1);
            for(double[] box:rotated){
                int x0=Arrays.binarySearch(xs,box[0]),x1=Arrays.binarySearch(xs,box[3]);
                int y0=Arrays.binarySearch(ys,box[1]),y1=Arrays.binarySearch(ys,box[4]);
                int z0=Arrays.binarySearch(zs,box[2]),z1=Arrays.binarySearch(zs,box[5]);
                for(int x=x0;x<x1;x++)for(int y=y0;y<y1;y++)for(int z=z0;z<z1;z++)bits.fill(x,y,z);
            }
            // One exact compressed grid. Repeated Shapes.or/optimize re-merges
            // hundreds of fractional axes and can stall mod initialization.
            SHAPES[turns]=new DirectShape(bits,xs,ys,zs);
        }
        CONSTRUCTION_NANOS=System.nanoTime()-start;
    }
    private static double[] coordinates(double[][] boxes,int axis){
        TreeSet<Double> values=new TreeSet<>();
        for(double[] box:boxes){values.add(box[axis]);values.add(box[axis+3]);}
        return values.stream().mapToDouble(Double::doubleValue).toArray();
    }
    private static final class DirectShape extends ArrayVoxelShape {
        private DirectShape(DiscreteVoxelShape bits,double[] xs,double[] ys,double[] zs){super(bits,xs,ys,zs);}
    }
    public static long constructionNanos(){return CONSTRUCTION_NANOS;}
    public static VoxelShape shape(Direction facing){return SHAPES[CinemaSeatGeometry.turns(facing)];}
    public static Vec3 mountPosition(BlockPos pos,Direction facing){
        double x=0.5,z=0.34720065304769926;
        for(int i=0;i<CinemaSeatGeometry.turns(facing);i++){double old=x;x=1-z;z=old;}
        return new Vec3(pos.getX()+x,pos.getY()+0.4602309045116529,pos.getZ()+z);
    }
    private DoubleSupportSeatGeometry(){}
